require_once __DIR__ . '/../includes/table_admin.php';if($_SERVER['REQUEST_METHOD']!=='POST')redirect('database/index.php');require_csrf_or_redirect('database/index.php');$table=posted('table');if(!posted('confirm')||!valid_table_name($table)){set_flash('danger','A valid, confirmed table deletion is required.');redirect('database/index.php');}try{db()->exec('DROP TABLE '.quoted_identifier($table));set_flash('success','Table '.$table.' was deleted.');}catch(PDOException $exception){set_flash('danger','The table could not be deleted because other database records depend on it.');}redirect('database/index.php');
